PREFIX uni: <http://university.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?professorName (GROUP_CONCAT(DISTINCT ?country; separator=", ") AS ?countries)
WHERE {
  {
    SELECT DISTINCT ?professor ?professorName ?country
    WHERE {
      ?professor a uni:Professor ;
                 uni:hasName ?professorName ;
                 uni:professorRank "Full" ;
                 uni:worksIn ?department .
      ?department uni:partOfUniversity ?university .
      ?university u

